function l(n,a="Europe/Moscow"){const t=new Intl.DateTimeFormat("en-CA",{timeZone:a,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(n);return["year","month","day"].map(e=>t.find(o=>o.type===e)?.value).join("-")}function d(n,a){const t=new Date(`${n}T12:00:00Z`);return t.setUTCDate(t.getUTCDate()+a),t.toISOString().slice(0,10)}function y(n,a,t="Europe/Moscow"){const e=Date.parse(`${n}T00:00:00Z`)+a*6e4;let o=e;for(let i=0;i<4;i++){const s=new Intl.DateTimeFormat("en-CA",{timeZone:t,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(new Date(o)),r=m=>Number(s.find(c=>c.type===m)?.value),u=Date.UTC(r("year"),r("month")-1,r("day"),r("hour"),r("minute"));if(u===e)return new Date(o);o+=e-u}return null}function f(n,a){const t=new Intl.DateTimeFormat("en-GB",{timeZone:a,hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(new Date(n));return Number(t.find(e=>e.type==="hour")?.value)*60+Number(t.find(e=>e.type==="minute")?.value)}export{y as a,l as b,d as c,f as s};
